@FokkeZB feel free to use the following test:

````ts
for (const host of ['localhost', '127.0.0.1', '0.0.0.0']) {
  test.only(`should detect the server if a web-server is already running on ${host}`, async ({ runInlineTest }, { workerIndex }) => {
    const port = workerIndex + 10500;
    const server = http.createServer((req: http.IncomingMessage, res: http.ServerResponse) => {
      res.end('<html><body>hello</body></html>');
    });
    await new Promise(resolve => server.listen(port, host, resolve));
    try {
      const result = await runInlineTest({
        'test.spec.ts': `
      const { test } = pwt;
      test('connect to the server via the baseURL', async ({baseURL, page}) => {
        await page.goto('/hello');
        expect(await page.textContent('body')).toBe('hello');
      });
    `,
        'playwright.config.ts': `
      module.exports = {
        webServer: {
          command: 'node -e "process.exit(1)"',
          port: ${port},
          reuseExistingServer: false,
        }
      };
    `,
      });
      expect(result.exitCode).toBe(1);
      expect(result.output).toContain(`Port ${port} is used, make sure that nothing is running on the port`);
    } finally {
      await new Promise(resolve => server.close(resolve));
    }
  });
}
```

issue_context.body:
**Context:**
- Playwright Version: 1.14
- Operating System: Mac
- Node.js version: 16.8.0
- Browser: N/A
- Extra: N/A

**Code Snippet**
```javascript
const net = require('net');

const existingServer = net.createServer();
existingServer.listen(3000, '127.0.0.1', () => {
  canBindPort(3000).then((result) => {
    console.log(`Can bind port: ${result}`);
    existingServer.close();
  });
});

async function canBindPort(port) {
  return new Promise((resolve) => {
    const server = net.createServer();

    server.on('error', () => resolve(false));
    server.listen(port, () => {
      server.close(() => {
        resolve(true);
      });
    });
  });
}
```

**Describe the bug**

Above is a copy of the `canBindPort` function from `node_modules/@playwright/test/lib/test/webServer.js`.
The script starts a server that listens on `127.0.0.1:3000`, then calls `canBindPort(3000)`, which returns `true` when it shouldn't. The function only returns `false` if the `existingServer` is started without passing a specific address.

Found this while using the [`Vite`](https://vitejs.dev/) dev server.
